161	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
162	        String idempotencyKey = idempotencyKey();
163	        if (idempotencyKey != null) {
164	            Integer existingId = this.idempotentCreates.get(idempotencyKey);
165	            if (existingId != null) {
166	                Owner existing = this.clinicService.findOwnerById(existingId);
167	                if (existing != null) {
168	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
169	                }
170	            }
171	        }
172	        normalizeAddress(ownerFieldsDto);
173	        rejectBlankOwnerFields(ownerFieldsDto);
174	        rejectInvalidPostcode(ownerFieldsDto);
175	        normalizeTelephone(ownerFieldsDto);
176	        normalizeEmail(ownerFieldsDto);
177	        String householdId = householdIdFor(ownerFieldsDto);
178	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
179	        rejectDuplicateIdentity(ownerFieldsDto, householdId);
180	        rejectHouseholdDuplicate(householdId, sharesHousehold);
