package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "selfLink", expression = "java(\"/api/owners/\" + owner.getId())")
    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "salutation", expression = "java(salutation(owner))")
    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.util.CustomerCode.region(owner.getCustomerCode()))")
    @Mapping(target = "timezone", expression = "java(timezone(owner))")
    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.util.LuhnCheckDigit.of(owner.getCustomerCode()))")
    @Mapping(target = "fiscalYear", expression = "java(org.springframework.samples.petclinic.util.FiscalYear.label(owner.getRegistrationDate()))")
    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", org.springframework.samples.petclinic.util.FiscalYear.yearOf(owner.getRegistrationDate()) % 100))")
    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
    @Mapping(target = "contactPreference", expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE)")
    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.util.OwnerIdentity.identityKey(owner))")
    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.util.TelephoneNormalizer.toDisplay(owner.getTelephone()))")
    OwnerDto toOwnerDto(Owner owner);

    /**
     * Derives the owner's IANA {@code timezone} from its locality (region) via a fixed
     * region-to-timezone table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne}
     * and {@code QLD -> Australia/Brisbane}. Returns {@code null} for a region not in the table.
     */
    default String timezone(Owner owner) {
        String region = org.springframework.samples.petclinic.util.CustomerCode.region(owner.getCustomerCode());
        if (region == null) {
            return null;
        }
        return switch (region) {
            case "NSW" -> "Australia/Sydney";
            case "VIC" -> "Australia/Melbourne";
            case "QLD" -> "Australia/Brisbane";
            default -> null;
        };
    }

    /**
     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against its
     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64 and
     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date is present.
     */
    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
        java.time.LocalDate birthDate = owner.getBirthDate();
        java.time.LocalDate asOf = owner.getRegistrationDate();
        if (birthDate == null || asOf == null) {
            return null;
        }
        int years = java.time.Period.between(birthDate, asOf).getYears();
        if (years < 18) {
            return OwnerDto.AgeBandEnum.MINOR;
        }
        if (years < 65) {
            return OwnerDto.AgeBandEnum.ADULT;
        }
        return OwnerDto.AgeBandEnum.SENIOR;
    }

    /**
     * Computes the owner's {@code membershipPoints}. Starts at 0; adds 2 when a non-blank email is
     * present; adds 1 when {@code namesakeCount} is 0; adds 2 for a household of 3 or more; adds 3
     * when at least one fiscal year has elapsed since {@code registrationDate} (measured from
     * {@code registrationDate} to today, counting 1-July boundaries crossed).
     */
    default int membershipPoints(Owner owner) {
        int points = 0;
        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
            points += 2;
        }
        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
            points += 1;
        }
        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
            points += 2;
        }
        java.time.LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate != null
                && org.springframework.samples.petclinic.util.FiscalYear.elapsed(
                        registrationDate, java.time.LocalDate.now()) >= 1) {
            points += 3;
        }
        return points;
    }

    /**
     * Reports the owner's {@code membershipLevel}. Uses the level stored on the owner when present
     * (as stamped on creation), otherwise falls back to the level {@linkplain #derivedMembershipLevel
     * derived} from its {@code membershipPoints}.
     */
    default int membershipLevel(Owner owner) {
        Integer stored = owner.getMembershipLevel();
        return stored != null ? stored : derivedMembershipLevel(owner);
    }

    /**
     * Derives the owner's {@code membershipLevel} from {@code membershipPoints}: 1 for 0-1 points,
     * 2 for 2-3 points, 3 for 4-5 points and 4 for 6 or more points.
     */
    default int derivedMembershipLevel(Owner owner) {
        int points = membershipPoints(owner);
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }

    /**
     * Composes the owner's {@code salutation} from its honorific {@code title} and {@code lastName}:
     * {@code title + ' ' + lastName} when a non-blank title is present, or just the {@code lastName}
     * when no title is given.
     */
    default String salutation(Owner owner) {
        String title = owner.getTitle();
        if (title == null || title.isBlank()) {
            return owner.getLastName();
        }
        return title + " " + owner.getLastName();
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

        .count();
}

/**
 * Counts the existing owners (before this create) belonging to the given household, i.e. those
 * whose stored {@code householdId} equals the value derived for the owner being created. The
 * count reflects only owners already persisted at the time of the create, so the owner being
 * created is never included; callers add one to obtain the household size after this create.
 *
 * @param householdId the household identifier derived for the owner being created (see
 *                    {@link HouseholdNormalizer#toHouseholdId})
 * @return the number of existing owners already sharing that household
 */
private int countHouseholdMembers(String householdId) {
    if (householdId == null) {
        return 0;
    }
    return (int) this.clinicService.findAllOwners().stream()
        .map(Owner::getHouseholdId)
        .filter(householdId::equals)
        .count();
}

/**
 * Derives the address an owner should carry from its submitted fields. The update path stamps an
 * owner with an address taken from the request, so routing that through this single method keeps the
 * derivation of "the owner's address" in one place, mirroring {@link #householdIdFor} for the
 * household id.
 *
 * @param ownerFieldsDto the submitted owner fields
 * @return the address to store on the owner
 */
private String addressFor(OwnerFieldsDto ownerFieldsDto) {
    return ownerFieldsDto.getAddress();
}

/**
 * Derives the household id an owner should carry from its submitted fields (see
 * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
 * household id, so routing them through this single method keeps them agreed on which of the
 * owner's fields key the household.
 *
 * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
 *                       {@link #rejectBlankOwnerFields} having already run on create)
 * @return the owner's household id
 */
private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
    return HouseholdNormalizer.toHouseholdId(
        ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
}

/**
 * Rejects creating an owner that would join an existing household without declaring itself a
 * member. The household is keyed on (last name, postcode) through the derived {@code householdId}
 * (see {@link HouseholdNormalizer#toHouseholdId}), so a second owner sharing an existing owner's
 * last name and postcode denotes the same household. Such a create is reported as a {@code 409
 * Conflict} unless it opts in with {@code sharesHousehold}, in which case it is accepted as a
 * declared household member. Only owners already persisted (before this create) are considered.
 *
 * @param householdId     the household id derived for the owner being created

